---@module 'hl'

-- Laptop multimedia keys for volume and LCD brightness (with OSD)

hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("swayosd-client --output-volume raise"), { repeating = true, locked = true })

hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("swayosd-client --output-volume lower"), { repeating = true, locked = true })

hl.bind("XF86AudioMute", hl.dsp.exec_cmd("swayosd-client --output-volume mute-toggle"), { repeating = true, locked = true })

hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("audio-input-mute"), { repeating = true, locked = true })

hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightness-display +5%"), { repeating = true, locked = true })

hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightness-display 5%-"), { repeating = true, locked = true })

hl.bind("SHIFT + XF86MonBrightnessUp", hl.dsp.exec_cmd("brightness-display 100%"), { repeating = true, locked = true })

hl.bind("SHIFT + XF86MonBrightnessDown", hl.dsp.exec_cmd("brightness-display 1%"), { repeating = true, locked = true })

hl.bind("XF86KbdBrightnessUp", hl.dsp.exec_cmd("brightness-keyboard up"), { repeating = true, locked = true })

hl.bind("XF86KbdBrightnessDown", hl.dsp.exec_cmd("brightness-keyboard down"), { repeating = true, locked = true })

hl.bind("XF86KbdLightOnOff", hl.dsp.exec_cmd("brightness-keyboard cycle"), { locked = true })

hl.bind("XF86TouchpadToggle", hl.dsp.exec_cmd("toggle-touchpad"), { locked = true })

hl.bind("XF86TouchpadOn", hl.dsp.exec_cmd("toggle-touchpad on"), { locked = true })

hl.bind("XF86TouchpadOff", hl.dsp.exec_cmd("toggle-touchpad off"), { locked = true })

-- Precise 1% multimedia adjustments with Alt modifier

hl.bind("ALT + XF86AudioRaiseVolume", hl.dsp.exec_cmd("swayosd-client --output-volume +1"), { repeating = true, locked = true })

hl.bind("ALT + XF86AudioLowerVolume", hl.dsp.exec_cmd("swayosd-client --output-volume -1"), { repeating = true, locked = true })

hl.bind("ALT + XF86MonBrightnessUp", hl.dsp.exec_cmd("brightness-display +1%"), { repeating = true, locked = true })

hl.bind("ALT + XF86MonBrightnessDown", hl.dsp.exec_cmd("brightness-display 1%-"), { repeating = true, locked = true })

-- Requires playerctl

hl.bind("XF86AudioNext", hl.dsp.exec_cmd("swayosd-client --playerctl next"), { locked = true })

hl.bind("XF86AudioPause", hl.dsp.exec_cmd("swayosd-client --playerctl play-pause"), { locked = true })

hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("swayosd-client --playerctl play-pause"), { locked = true })

hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("swayosd-client --playerctl previous"), { locked = true })

-- Switch audio output with Super + Mute

hl.bind("SUPER + XF86AudioMute", hl.dsp.exec_cmd("audio-output-switch"), { locked = true })
